<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref } from 'vue'
import { preferencesState } from '../store/preferences'
import { physicsState, pushHistory } from '../store/physics'
import { createInputBinding, normalizeInputMap } from '../runtime/input'
import { gameplayRuntime } from '../runtime/GameplayRuntime'
import { UI_DEVICE_PRESETS } from '../runtime/uiProduction'
import {
  applyOrientationPolicy, createVirtualControl, deviceInputSettings, deviceRuntimeState, deviceSensorState,
  performHaptic, refreshDeviceCapabilities, requestDeviceSensorPermission, type GamepadAxisCalibration, type VirtualControlKind
} from '../runtime/deviceInput'

type Tab = 'preview' | 'virtual' | 'gamepad' | 'sensors'
const activeTab = ref<Tab>('preview'), presetIndex = ref(4), rotated = ref(false), connectedGamepads = ref<Gamepad[]>([])
const captureAction = ref(physicsState.inputMap[0]?.name ?? ''), captureStatus = ref(''), captureDeadline = ref(0)
let refreshTimer = 0, captureFrame = 0
const words = {
  en: { title:'Devices & mobile input', subtitle:'Preview, remap, and test the exact runtime controls.', preview:'Preview', virtual:'Virtual controls', gamepad:'Gamepad', sensors:'Sensors', rotate:'Rotate', safe:'Safe area', dpi:'Reference DPI', enableVirtual:'Enable virtual controls', visibility:'Visibility', touchOnly:'Touch devices', always:'Always preview', addControl:'Add control', noControls:'No virtual controls yet.', label:'Label', action:'Action', kind:'Control', anchor:'Anchor', size:'Size', opacity:'Opacity', haptic:'Haptic', remove:'Remove', connected:'Connected controllers', none:'No controller detected.', remap:'Capture binding', chooseAction:'Action to remap', waiting:'Press a key or gamepad control…', calibration:'Axis calibration', addCalibration:'Add axis calibration', axis:'Axis', minimum:'Minimum', center:'Center', maximum:'Maximum', deadzone:'Dead zone', invert:'Invert', orientation:'Orientation', auto:'Automatic', portrait:'Portrait', landscape:'Landscape', applyOrientation:'Apply orientation', enableSensors:'Enable motion sensors', requestPermission:'Request sensor permission', permission:'Permission', liveValues:'Live values', testHaptic:'Test haptic', saveHint:'Changes are stored with the project.', button:'Button', stick:'Stick', dpad:'D-pad', bottomLeft:'Bottom left', bottomRight:'Bottom right', topLeft:'Top left', topRight:'Top right', captured:'Binding captured', timeout:'Capture timed out', capability:'Host capability' },
  de: { title:'Geräte & mobile Eingabe', subtitle:'Laufzeitsteuerung exakt ansehen, neu belegen und testen.', preview:'Vorschau', virtual:'Virtuelle Steuerung', gamepad:'Gamepad', sensors:'Sensoren', rotate:'Drehen', safe:'Sicherer Bereich', dpi:'Referenz-DPI', enableVirtual:'Virtuelle Steuerung aktivieren', visibility:'Sichtbarkeit', touchOnly:'Touch-Geräte', always:'Immer anzeigen', addControl:'Steuerung hinzufügen', noControls:'Noch keine virtuelle Steuerung.', label:'Beschriftung', action:'Aktion', kind:'Steuerung', anchor:'Anker', size:'Größe', opacity:'Deckkraft', haptic:'Haptik', remove:'Entfernen', connected:'Verbundene Controller', none:'Kein Controller erkannt.', remap:'Belegung erfassen', chooseAction:'Neu zu belegende Aktion', waiting:'Taste oder Gamepad-Steuerung drücken…', calibration:'Achsenkalibrierung', addCalibration:'Achsenkalibrierung hinzufügen', axis:'Achse', minimum:'Minimum', center:'Mitte', maximum:'Maximum', deadzone:'Totzone', invert:'Umkehren', orientation:'Ausrichtung', auto:'Automatisch', portrait:'Hochformat', landscape:'Querformat', applyOrientation:'Ausrichtung anwenden', enableSensors:'Bewegungssensoren aktivieren', requestPermission:'Sensorberechtigung anfragen', permission:'Berechtigung', liveValues:'Live-Werte', testHaptic:'Haptik testen', saveHint:'Änderungen werden im Projekt gespeichert.', button:'Taste', stick:'Stick', dpad:'Steuerkreuz', bottomLeft:'Unten links', bottomRight:'Unten rechts', topLeft:'Oben links', topRight:'Oben rechts', captured:'Belegung erfasst', timeout:'Erfassung abgelaufen', capability:'Host-Fähigkeit' },
  zh: { title:'设备与移动输入', subtitle:'预览、重新绑定并测试实际运行时控制。', preview:'设备预览', virtual:'虚拟控制', gamepad:'手柄', sensors:'传感器', rotate:'旋转', safe:'安全区域', dpi:'参考 DPI', enableVirtual:'启用虚拟控制', visibility:'显示条件', touchOnly:'仅触控设备', always:'始终预览', addControl:'添加控制', noControls:'尚无虚拟控制。', label:'标签', action:'动作', kind:'控件', anchor:'锚点', size:'大小', opacity:'不透明度', haptic:'触觉反馈', remove:'移除', connected:'已连接控制器', none:'未检测到控制器。', remap:'捕获绑定', chooseAction:'要重新绑定的动作', waiting:'请按键或操作手柄…', calibration:'摇杆轴校准', addCalibration:'添加轴校准', axis:'轴', minimum:'最小值', center:'中心', maximum:'最大值', deadzone:'死区', invert:'反转', orientation:'方向', auto:'自动', portrait:'竖屏', landscape:'横屏', applyOrientation:'应用方向', enableSensors:'启用运动传感器', requestPermission:'请求传感器权限', permission:'权限', liveValues:'实时数值', testHaptic:'测试触觉反馈', saveHint:'更改会随项目保存。', button:'按钮', stick:'摇杆', dpad:'方向键', bottomLeft:'左下', bottomRight:'右下', topLeft:'左上', topRight:'右上', captured:'已捕获绑定', timeout:'捕获已超时', capability:'主机能力' }
} as const
function l(key: keyof typeof words.en): string { return (words[preferencesState.locale] ?? words.en)[key] }

const tabs = computed(() => [{ id:'preview' as const,label:l('preview') },{ id:'virtual' as const,label:l('virtual') },{ id:'gamepad' as const,label:l('gamepad') },{ id:'sensors' as const,label:l('sensors') }])
const preset = computed(() => UI_DEVICE_PRESETS[presetIndex.value] ?? UI_DEVICE_PRESETS[4])
const previewWidth = computed(() => rotated.value ? preset.value.height : preset.value.width)
const previewHeight = computed(() => rotated.value ? preset.value.width : preset.value.height)
const previewSafe = computed(() => rotated.value ? { left:preset.value.safeArea.top, top:preset.value.safeArea.right, right:preset.value.safeArea.bottom, bottom:preset.value.safeArea.left } : preset.value.safeArea)
const previewStyle = computed(() => ({ aspectRatio:`${previewWidth.value}/${previewHeight.value}`, width: previewWidth.value > previewHeight.value ? 'min(100%,560px)' : 'min(62%,300px)' }))
const controlKinds: VirtualControlKind[] = ['button','stick','dpad']
const anchors = ['bottom-left','bottom-right','top-left','top-right'] as const
function anchorLabel(anchor: typeof anchors[number]): string { return l(({ 'bottom-left':'bottomLeft', 'bottom-right':'bottomRight', 'top-left':'topLeft', 'top-right':'topRight' } as const)[anchor]) }
const calibrationDefaults = (): GamepadAxisCalibration => ({ deviceId:'*', axis:0, minimum:-1, center:0, maximum:1, deadzone:.12, invert:false })

function commit(label = 'Edit device input'): void { pushHistory(label) }
function addControl(): void { const action = physicsState.inputMap.find(item => item.kind === 'vector2')?.name ?? physicsState.inputMap[0]?.name ?? 'Move'; deviceInputSettings.virtualControls.push(createVirtualControl(action, physicsState.inputMap.find(item => item.name === action)?.kind === 'vector2' ? 'stick' : 'button', deviceInputSettings.virtualControls.length)); deviceInputSettings.virtualControlsEnabled = true; commit('Add virtual control') }
function removeControl(index: number): void { const control = deviceInputSettings.virtualControls[index]; if (control) gameplayRuntime.input.releaseVirtualAction(control.action); deviceInputSettings.virtualControls.splice(index,1); commit('Remove virtual control') }
function addCalibration(): void { if (deviceInputSettings.gamepadCalibrations.length >= 128) return; deviceInputSettings.gamepadCalibrations.push(calibrationDefaults()); commit('Add gamepad calibration') }
function removeCalibration(index:number): void { deviceInputSettings.gamepadCalibrations.splice(index,1); commit('Remove gamepad calibration') }
function refreshDevices(): void { refreshDeviceCapabilities(); connectedGamepads.value = typeof navigator !== 'undefined' && navigator.getGamepads ? Array.from(navigator.getGamepads()).filter((item):item is Gamepad => Boolean(item)) : [] }
function bindingCaptured(device:'keyboard'|'gamepad-button'|'gamepad-axis', code:string): void {
  const action = physicsState.inputMap.find(item => item.name === captureAction.value)
  if (!action) return stopCapture()
  const index = action.bindings.findIndex(binding => binding.device === device)
  const binding = createInputBinding(device, code)
  if (index >= 0) action.bindings.splice(index,1,binding); else action.bindings.push(binding)
  const normalized = normalizeInputMap(physicsState.inputMap); physicsState.inputMap.splice(0,physicsState.inputMap.length,...normalized)
  pushHistory('Remap input action'); captureStatus.value = `${l('captured')}: ${device} ${code}`; stopCapture(false)
}
function captureKey(event:KeyboardEvent): void { event.preventDefault(); if (event.key === 'Escape') { stopCapture(); return }; bindingCaptured('keyboard', event.code) }
function pollGamepad(): void {
  if (!captureDeadline.value) return
  if (performance.now() >= captureDeadline.value) { captureStatus.value = l('timeout'); stopCapture(false); return }
  for (const pad of Array.from(navigator.getGamepads?.() ?? [])) {
    if (!pad) continue
    const button = pad.buttons.findIndex(value => value.pressed || value.value > .65); if (button >= 0) { bindingCaptured('gamepad-button', String(button)); return }
    const axis = pad.axes.findIndex(value => Math.abs(value) > .7); if (axis >= 0) { bindingCaptured('gamepad-axis', String(axis)); return }
  }
  captureFrame = requestAnimationFrame(pollGamepad)
}
function beginCapture(): void { stopCapture(); captureStatus.value = l('waiting'); captureDeadline.value = performance.now()+10_000; window.addEventListener('keydown',captureKey,true); captureFrame=requestAnimationFrame(pollGamepad) }
function stopCapture(clear=true): void { window.removeEventListener('keydown',captureKey,true); if(captureFrame)cancelAnimationFrame(captureFrame); captureFrame=0; captureDeadline.value=0; if(clear)captureStatus.value='' }
async function sensorPermission(): Promise<void> { await requestDeviceSensorPermission() }
async function orient(): Promise<void> { await applyOrientationPolicy() }

onMounted(() => { refreshDevices(); refreshTimer=window.setInterval(refreshDevices,1000) })
onBeforeUnmount(() => { window.clearInterval(refreshTimer); stopCapture(); gameplayRuntime.input.releaseAllVirtualActions() })
</script>

<template>
  <section class="device-studio">
    <header><div><strong>{{ l('title') }}</strong><p>{{ l('subtitle') }}</p></div><span>{{ deviceRuntimeState.capabilities.orientation }} · {{ deviceRuntimeState.capabilities.devicePixelRatio.toFixed(2) }}×</span></header>
    <nav :aria-label="l('title')"><button v-for="tab in tabs" :key="tab.id" :class="{active:activeTab===tab.id}" @click="activeTab=tab.id">{{ tab.label }}</button></nav>
    <div v-if="activeTab==='preview'" class="page preview-page">
      <div class="toolbar"><select v-model.number="presetIndex"><option v-for="(item,index) in UI_DEVICE_PRESETS" :key="item.id" :value="index">{{ item.label }} · {{ item.width }}×{{ item.height }}</option></select><button @click="rotated=!rotated">↻ {{ l('rotate') }}</button></div>
      <div class="device-frame" :class="{portrait:previewHeight>previewWidth}" :style="previewStyle">
        <div class="device-camera" aria-hidden="true"></div><div class="safe-frame" :style="{left:`${previewSafe.left/previewWidth*100}%`,right:`${previewSafe.right/previewWidth*100}%`,top:`${previewSafe.top/previewHeight*100}%`,bottom:`${previewSafe.bottom/previewHeight*100}%`}"><span>{{ l('safe') }}</span><i></i></div>
        <div class="target-sample">44 × 44</div>
      </div>
      <dl><div><dt>{{ l('dpi') }}</dt><dd>{{ preset.dpi }}×</dd></div><div><dt>{{ l('orientation') }}</dt><dd>{{ previewWidth>previewHeight?l('landscape'):l('portrait') }}</dd></div><div><dt>{{ l('safe') }}</dt><dd>{{ previewSafe.left }}/{{ previewSafe.top }}/{{ previewSafe.right }}/{{ previewSafe.bottom }}</dd></div></dl>
    </div>
    <div v-else-if="activeTab==='virtual'" class="page">
      <div class="setting-line"><span>{{ l('enableVirtual') }}</span><input v-model="deviceInputSettings.virtualControlsEnabled" type="checkbox" @change="commit()"></div>
      <div class="setting-line"><span>{{ l('visibility') }}</span><select v-model="deviceInputSettings.showVirtualControls" @change="commit()"><option value="touch-only">{{ l('touchOnly') }}</option><option value="always">{{ l('always') }}</option></select></div>
      <article v-for="(control,index) in deviceInputSettings.virtualControls" :key="control.id" class="control-card" @change="commit()">
        <header><strong>{{ control.label || control.action }}</strong><button class="danger" @click="removeControl(index)">× {{ l('remove') }}</button></header>
        <div class="fields"><label>{{ l('label') }}<input v-model.trim="control.label" maxlength="80"></label><label>{{ l('action') }}<select v-model="control.action"><option v-for="action in physicsState.inputMap" :key="action.name">{{ action.name }}</option></select></label><label>{{ l('kind') }}<select v-model="control.kind"><option v-for="kind in controlKinds" :key="kind" :value="kind">{{ l(kind) }}</option></select></label><label>{{ l('anchor') }}<select v-model="control.anchor"><option v-for="anchor in anchors" :key="anchor" :value="anchor">{{ anchorLabel(anchor) }}</option></select></label><label>{{ l('size') }}<input v-model.number="control.size" type="number" min="40" max="320"></label><label>{{ l('opacity') }}<input v-model.number="control.opacity" type="number" min=".2" max="1" step=".05"></label><label>{{ l('haptic') }}<input v-model.number="control.hapticMs" type="number" min="0" max="100"></label><label>Offset X / Y<div class="pair"><input v-model.number="control.offsetX" type="number" min="0" max="2000"><input v-model.number="control.offsetY" type="number" min="0" max="2000"></div></label></div>
      </article>
      <p v-if="!deviceInputSettings.virtualControls.length">{{ l('noControls') }}</p><button class="primary" @click="addControl">+ {{ l('addControl') }}</button>
    </div>
    <div v-else-if="activeTab==='gamepad'" class="page">
      <h3>{{ l('connected') }}</h3><ul class="devices"><li v-for="pad in connectedGamepads" :key="pad.index"><strong>{{ pad.id }}</strong><span>#{{ pad.index }} · {{ pad.mapping || 'raw' }}</span></li></ul><p v-if="!connectedGamepads.length">{{ l('none') }}</p>
      <div class="capture"><label>{{ l('chooseAction') }}<select v-model="captureAction"><option v-for="action in physicsState.inputMap" :key="action.name">{{ action.name }}</option></select></label><button :disabled="!captureAction" @click="beginCapture">◉ {{ l('remap') }}</button><output aria-live="polite">{{ captureStatus }}</output></div>
      <h3>{{ l('calibration') }}</h3><article v-for="(item,index) in deviceInputSettings.gamepadCalibrations" :key="`${item.deviceId}:${item.axis}:${index}`" class="calibration" @change="commit()"><label>ID<input v-model.trim="item.deviceId"></label><label>{{ l('axis') }}<input v-model.number="item.axis" type="number" min="0" max="63"></label><label>{{ l('minimum') }}<input v-model.number="item.minimum" type="number" min="-1" max="1" step=".01"></label><label>{{ l('center') }}<input v-model.number="item.center" type="number" min="-1" max="1" step=".01"></label><label>{{ l('maximum') }}<input v-model.number="item.maximum" type="number" min="-1" max="1" step=".01"></label><label>{{ l('deadzone') }}<input v-model.number="item.deadzone" type="number" min="0" max=".95" step=".01"></label><label class="check">{{ l('invert') }}<input v-model="item.invert" type="checkbox"></label><button class="danger" @click="removeCalibration(index)">×</button></article><button @click="addCalibration">+ {{ l('addCalibration') }}</button>
    </div>
    <div v-else class="page">
      <div class="setting-line"><span>{{ l('orientation') }}</span><select v-model="deviceInputSettings.orientation" @change="commit()"><option value="auto">{{ l('auto') }}</option><option value="portrait">{{ l('portrait') }}</option><option value="landscape">{{ l('landscape') }}</option></select><button @click="orient">{{ l('applyOrientation') }}</button></div>
      <div class="setting-line"><span>{{ l('enableSensors') }}</span><input v-model="deviceInputSettings.motionSensorsEnabled" type="checkbox" @change="commit()"><button :disabled="!deviceInputSettings.motionSensorsEnabled" @click="sensorPermission">{{ l('requestPermission') }}</button></div>
      <dl><div><dt>{{ l('permission') }}</dt><dd>{{ deviceSensorState.permission }}</dd></div><div><dt>{{ l('capability') }}</dt><dd>{{ deviceRuntimeState.capabilities.motionSensors?'✓':'—' }}</dd></div><div><dt>Orientation β/γ/α</dt><dd>{{ deviceSensorState.orientation.map(v=>v.toFixed(1)).join(' / ') }}</dd></div><div><dt>Acceleration</dt><dd>{{ deviceSensorState.acceleration.map(v=>v.toFixed(2)).join(' / ') }}</dd></div><div><dt>Rotation</dt><dd>{{ deviceSensorState.rotationRate.map(v=>v.toFixed(1)).join(' / ') }}</dd></div></dl>
      <button @click="performHaptic(18)">⌁ {{ l('testHaptic') }}</button><p class="hint">{{ l('saveHint') }}</p><p v-if="deviceRuntimeState.lastError" class="error" role="alert">{{ deviceRuntimeState.lastError }}</p>
    </div>
  </section>
</template>

<style scoped>
.device-studio{grid-column:1/-1;min-width:0;overflow:hidden;border:1px solid var(--border-subtle);border-radius:var(--radius-lg);background:var(--surface-1);box-shadow:var(--shadow-sm)}.device-studio>header{min-height:58px;padding:10px 14px;display:flex;align-items:center;justify-content:space-between;gap:12px;border-bottom:1px solid var(--border-subtle)}.device-studio>header div{min-width:0}.device-studio>header strong{font-size:15px}.device-studio>header p{margin:3px 0 0;color:var(--text-muted);font-size:12px}.device-studio>header>span{color:var(--accent);font-size:11px;white-space:nowrap}.device-studio>nav{padding:5px;display:flex;gap:4px;overflow-x:auto;border-bottom:1px solid var(--border-subtle);background:var(--surface-2)}.device-studio>nav button{min-width:max-content;min-height:32px;padding:0 11px;border:0;border-radius:8px;color:var(--text-muted);background:transparent}.device-studio>nav button.active{color:var(--accent);background:var(--accent-soft)}.page{padding:14px;display:grid;gap:10px}.toolbar,.setting-line,.capture{display:flex;align-items:center;gap:8px;flex-wrap:wrap}.setting-line>span{min-width:170px;flex:1}.setting-line select{min-width:150px}.page button{min-height:34px;padding:0 10px;border:1px solid var(--border-subtle);border-radius:8px;background:var(--surface-2)}.page button.primary{justify-self:start;color:var(--accent-contrast);border-color:var(--accent);background:var(--accent)}.page button.danger{color:var(--danger)}.preview-page{justify-items:center}.toolbar{width:100%;justify-content:center}.device-frame{position:relative;max-height:390px;overflow:hidden;border:8px solid var(--surface-3);border-radius:28px;background:linear-gradient(145deg,#17253c,#0e141e);box-shadow:0 18px 46px rgba(0,0,0,.28);transition:width 220ms ease,aspect-ratio 220ms ease}.device-frame.portrait{border-radius:34px}.device-camera{position:absolute;z-index:2;top:7px;left:50%;width:min(26%,100px);height:8px;transform:translateX(-50%);border-radius:99px;background:rgba(0,0,0,.62)}.safe-frame{position:absolute;border:1px dashed #74b4ff;border-radius:8px}.safe-frame span{position:absolute;top:4px;left:6px;color:#9ac8ff;font-size:11px}.safe-frame i{position:absolute;inset:50% auto auto 50%;width:44px;height:44px;transform:translate(-50%,-50%);border:1px solid rgba(255,255,255,.6);border-radius:10px}.target-sample{position:absolute;right:10px;bottom:10px;width:44px;height:44px;display:grid;place-items:center;border-radius:10px;color:#fff;background:#397dd3;font-size:11px}.page dl{width:100%;margin:0;display:grid;grid-template-columns:repeat(auto-fit,minmax(130px,1fr));gap:6px}.page dl div{padding:8px;border:1px solid var(--border-subtle);border-radius:8px;background:var(--surface-2)}.page dt{color:var(--text-muted);font-size:11px}.page dd{margin:3px 0 0;overflow-wrap:anywhere;font-size:11px}.control-card{padding:10px;border:1px solid var(--border-subtle);border-radius:10px;background:var(--surface-2)}.control-card>header{display:flex;align-items:center;justify-content:space-between}.fields,.calibration{display:grid;grid-template-columns:repeat(auto-fit,minmax(125px,1fr));gap:7px}.fields label,.calibration label,.capture label{min-width:0;display:flex;flex-direction:column;gap:3px;color:var(--text-muted);font-size:11px}.fields input,.fields select,.calibration input,.capture select{width:100%;min-width:0}.pair{display:grid;grid-template-columns:1fr 1fr;gap:4px}.devices{margin:0;padding:0;display:grid;gap:5px;list-style:none}.devices li{padding:7px 9px;display:flex;justify-content:space-between;gap:8px;border-radius:8px;background:var(--surface-2)}.devices strong{max-width:72%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.devices span{color:var(--text-muted);font-size:11px}.capture{padding:9px;border:1px solid var(--border-subtle);border-radius:10px}.capture label{min-width:180px;flex:1}.capture output{width:100%;color:var(--accent);font-size:11px}.calibration{padding:8px;border:1px solid var(--border-subtle);border-radius:9px}.calibration .check{justify-content:flex-end;align-items:center}.calibration .check input{width:auto}.hint{color:var(--text-muted);font-size:11px}.error{color:var(--danger)}h3{margin:4px 0 0;font-size:12px}@media(max-width:680px){.page{padding:10px}.setting-line>span{min-width:100%;}.device-studio>header>span{display:none}.fields,.calibration{grid-template-columns:1fr 1fr}}@media(prefers-reduced-motion:reduce){.device-frame{transition:none}}
</style>

